 @Override public boolean performClick(){super.performClick();return true;} private void announce(String m){if(s.accessibilityAnnouncements==1)announceForAccessibility(m);} @Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;performClick();float x=e.getX(),y=e.getY(),w=getWidth(),h=Math.max(1f,getHeight()-bottomInset);reaction="";if(screen==0){if(y<h*.115f&&x>w*.82f)screen=5;else if(y>h*.475f&&y<h*.585f)screen=1;else if(y>h*.585f&&y<h*.685f){if(x<w*.34f){int beforeCoins=s.coins;if(s.claimDaily(getContext())){reaction="Presente diário! +"+(s.coins-beforeCoins)+" moedas"+(s.dailyStreak%3==0?" e +1 ovo!":"!");reactions.show(this,reaction,s.accessibilityAnnouncements==1);}else{reaction="Presente de hoje já recebido!";reactions.show(this,reaction,s.accessibilityAnnouncements==1);}}else if(x<w*.66f){if(s.eggs<=0){reaction="Você ainda não tem ovos. Complete fases para ganhar!";reactions.show(this,reaction,s.accessibilityAnnouncements==1);}else if(s.collectionComplete()){reaction="Coleção completa! Todos os monstrinhos foram descobertos.";reactions.show(this,reaction,s.accessibilityAnnouncements==1);}else{long before=s.ownedMask;s.hatch(getContext());long diff=s.ownedMask&~before;if(diff!=0L){lastHatch=Long.numberOfTrailingZeros(diff);screen=8;}}}else screen=10;}else if(y>h*.685f&&y<h*.785f){if(x<w*.30f)screen=3;else if(x<w*.56f)screen=4;else screen=5;}else if(y>h*.785f&&y<h*.875f){screen=7;achievementPage=0;AchievementCatalog.Card[] a=AchievementCatalog.snapshot(getContext());StringBuilder d=new StringBuilder("Conquistas. ");for(AchievementCatalog.Card card:a)d.append(card.accessibilityLabel()).append(' ');announce(d.toString());}else if(y>h*.875f){screen=6;challengeScore=0;misses=0;challengeStartedAt=System.currentTimeMillis();}}else if(screen==1){if(levelPage==0){if(y<h*.115f&&x>w*.82f)screen=5;else if(y>h*.86f){if(x<w*.28f)levelPage=0;else if(x>w*.72f)levelPage=1;else screen=0;}else{float radius=w*.09f;for(int i=0;i<10;i++){float cx=w*MAP_X[i],cy=h*MAP_Y[i];float dx=x-cx,dy=y-cy;int n=i+1;if(dx*dx+dy*dy<radius*radius&&s.levelUnlocked(n)){selectedLevel=n;taps=misses=0;gameplayReactions.resetRound();s.beginLevel(getContext());screen=2;break;}}}}else{if(y>h*.88f)screen=0;else if(y>h*.75f&&y<h*.87f){if(x<w*.35f)levelPage=Math.max(0,levelPage-1);else if(x>w*.65f)levelPage=Math.min(2,levelPage+1);}else{int start=levelPage*10+1;for(int i=0;i<10;i++){int n=start+i,row=i/5,col=i%5;float cx=w*(.12f+col*.19f),cy=h*(.29f+row*.25f);if((x-cx)*(x-cx)+(y-cy)*(y-cy)<3000&&s.levelUnlocked(n)){selectedLevel=n;taps=misses=0;gameplayReactions.resetRound();s.beginLevel(getContext());screen=2;break;}}}}}else if(screen==2){if(y>h*.86f){screen=1;}else{float dx=x-w*targetX,dy=y-h*targetY;if(dx*dx+dy*dy<18000){taps++;gameplayReactions.onHit(this,s.accessibilityAnnouncements==1);if(s.shouldAnimate()){targetX=.2f+rng.nextFloat()*.6f;targetY=.32f+rng.nextFloat()*.35f;}if(taps>=s.targetTapsForLevel(selectedLevel)){int earned=misses==0?3:misses==1?2:1;int beforeCoins=s.coins;s.finishLevel(getContext(),selectedLevel,earned);resultStars=earned;resultCoins=s.coins-beforeCoins;resultStage=selectedLevel;gameplayReactions.onLevelComplete(this,earned,s.isBoss(selectedLevel),s.accessibilityAnnouncements==1);screen=9;}}else{misses++;gameplayReactions.onMiss(this,misses,s.accessibilityAnnouncements==1);if(misses>=3){s.failLevel(getContext(),selectedLevel);screen=1;}}}}else if(screen==3){if(y>h*.80f&&y<h*.92f){if(x<w*.32f)albumPage=1-albumPage;else if(x<w*.68f){CollectionRewardClaim r=CollectionRewardClaim.claimNext(s,getContext());announce(r.message);reaction=r.message;}else screen=0;}else{reaction=AlbumInteraction.selectFavorite(getContext(),s,w,h,albumPage,x,y);if(!reaction.isEmpty())reactions.show(this,reaction,s.accessibilityAnnouncements==1);}}else if(screen==4){if(y>h*.85f){if(x<w*.5f)houseReactions.selectOrBuyDecor(getContext(),s,(s.houseDecor+1)%4);else screen=0;}else if(y>h*.73f){if(x<w*.5f)houseReactions.care(getContext(),s);else houseReactions.evolve(getContext(),s);}}else if(screen==5){if(y>h*.85f)screen=0;else if(y>h*.25f&&y<h*.37f)s.toggleSound(getContext());else if(y>h*.37f&&y<h*.48f)s.toggleVibration(getContext());else if(y>h*.48f&&y<h*.59f)s.toggleHints(getContext());else if(y>h*.59f&&y<h*.70f)s.toggleAccessibilityAnnouncements(getContext());else if(y>h*.70f&&y<h*.84f){if(x<w*.25f)s.toggleReducedMotion(getContext());else if(x<w*.5f)s.toggleLargeText(getContext());else if(x<w*.75f)s.toggleHighContrast(getContext());else s.toggleColorBlindMode(getContext());}}else if(screen==8){if(y>h*.80f){if(x<w*.54f){albumPage=Math.max(0,Math.min(1,lastHatch/16));screen=3;}else screen=0;}}else if(screen==9){if(y>h*.78f){final boolean goNext=x>=w*.5f;Runnable cont=()->{if(!goNext)screen=1;else{int next=Math.min(30,resultStage+1);if(next!=resultStage&&s.levelUnlocked(next)){selectedLevel=next;taps=misses=0;s.beginLevel(getContext());screen=2;}else screen=1;}invalidate();};if(s.interstitialDue()&&!s.adsRemoved()&&getContext() instanceof MainActivity){boolean shown=((MainActivity)getContext()).showInterstitialThen(cont);if(shown)s.markInterstitialShown(getContext());}else cont.run();}}else if(screen==10){if(y>h*.86f)screen=0;else if(getContext() instanceof MainActivity){MainActivity a=(MainActivity)getContext();if(y>h*.20f&&y<h*.36f)a.buyProduct(MonetizationManager.COINS_SMALL);else if(y>h*.36f&&y<h*.52f)a.buyProduct(MonetizationManager.COINS_MEDIUM);else if(y>h*.52f&&y<h*.68f){if(s.adsRemoved())showMonetizationMessage("Anúncios automáticos já estão removidos.");else a.buyProduct(MonetizationManager.REMOVE_ADS);}else if(y>h*.68f&&y<h*.84f)a.showRewardedCoins();}}else if(screen==7){if(y>h*.82f){if(x<w*.5f){achievementPage=1-achievementPage;AchievementCatalog.Card[] a=AchievementCatalog.snapshot(getContext());int start=achievementPage*4;StringBuilder d=new StringBuilder();for(int i=start;i<Math.min(start+4,a.length);i++)d.append(a[i].accessibilityLabel()).append(' ');announce(d.toString());}else screen=0;}}else{if(y>h*.86f)screen=0;else{float dx=x-w*targetX,dy=y-h*targetY;if(dx*dx+dy*dy<18000){challengeScore++;if(s.shouldAnimate()){targetX=.18f+rng.nextFloat()*.64f;targetY=.30f+rng.nextFloat()*.4f;}if(challengeScore>=10){s.finishChallenge(getContext(),challengeScore);challengeStartedAt=0;screen=0;}}else if(++misses>=3){s.finishChallenge(getContext(),challengeScore);challengeStartedAt=0;screen=0;}}}if(!reaction.isEmpty())announce(reaction);invalidate();return true;}
